<?php
declare(strict_types=1);
namespace App\Application\Study\Service;
use App\Application\Study\DTO\Request\GetNotebookRequestDto;use App\Application\Study\DTO\Response\NotebookStatisticsResponseDto;use App\Domain\Study\Repository\NotebookProgressReaderInterface;use App\Domain\Study\Repository\NotebookRepositoryInterface;
final class GetNotebookStatisticsService { public function __construct(private readonly NotebookRepositoryInterface $notebooks,private readonly NotebookProgressReaderInterface $progress,private readonly \DateTimeZone $utc=new \DateTimeZone('UTC')){} public function getForUser(string $userId,GetNotebookRequestDto $request):?NotebookStatisticsResponseDto{$notebook=$this->notebooks->findByIdForUser($request->id,$userId);if($notebook===null)return null;$latest=[];foreach($this->progress->completedAnswersForNotebook($userId,$notebook->id) as $answer){$latest[$answer->questionId]??=$answer;}$answers=array_values($latest);$correct=count(array_filter($answers,static fn($answer):bool=>$answer->isCorrect));$answered=count($answers);$elapsed=array_sum(array_map(static fn($answer):int=>$answer->elapsedSeconds,$answers));return new NotebookStatisticsResponseDto(count($notebook->selection->questionIds),$answered,$correct,$answered-$correct,$answered===0?0.0:round(($correct/$answered)*100,2),$answered===0?0.0:round($elapsed/$answered,2),$notebook->elapsedSecondsAt(new \DateTimeImmutable('now',$this->utc)),array_keys($latest));} }
